import sympy

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def has_roots_mod_p(f, p):
    # Compute the Legendre symbol (p|f(x))
    # This is equivalent to checking if f(x) has a root mod p
    # for all x in {0, 1,..., p-1}
    for x in range(p):
        if f.subs(x, x) % p == 0:
            return False
    return True

# Check for odd primes p > 3
for p in range(7, 100, 2):  # Start from 7, since 5 is not an odd prime
    if is_prime(p):
        f = sympy.symbols('x')**2 + 3*sympy.symbols('x') + 3
        if has_roots_mod_p(f, p):
            print(f"p = {p} has roots mod p")
        else:
            print(f"p = {p} does not have roots mod p")

# Check for p ≡ 1 (mod 3)
for p in range(3, 100, 3):  # Start from 3, since 0 is not an odd prime
    if is_prime(p):
        f = sympy.symbols('x')**2 + 3*sympy.symbols('x') + 3
        if has_roots_mod_p(f, p):
            print(f"p = {p} has roots mod p")
